import{_ as t,l as i,o as a,c as n,v as r,p as l,x as o,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"Windows Kerberos 攻击","description":"","frontmatter":{"title":"Windows Kerberos 攻击","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/windows-kerberos-attacks.md","filePath":"cs/windows-kerberos-attacks.md","lastUpdated":1789023840000}'),p={name:"cs/windows-kerberos-attacks.md"};function E(T,e,b,_,u,B){const s=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="windows-kerberos-攻击" tabindex="-1">Windows Kerberos 攻击 <a class="header-anchor" href="#windows-kerberos-攻击" aria-label="Permalink to &quot;Windows Kerberos 攻击&quot;">​</a></h1><div class="epigraph"><p>Kerberos 把票据当能力。票据太强、哈希可离线、委派过宽时，域内横向变成协议合同问题。防御是限制委派、保护 KRBTGT、短寿命，而不是默记攻击商品名。</p><footer>—— 据 RFC 4120；Bellovin and Merritt 对 Kerberos 的早期讨论；Microsoft 对委派与 PAC 的文档；对照主干[Kerberos](/cs/kerberos)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/linux-privesc">Linux 提权</a>是主机。缺口是<strong>域身份</strong>：主干 Kerberos 直觉已有 TGT。本课收 Windows 域常见合同失败（黄金票据一类只作机制点名），不给复制步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TGT 与服务票若被盗，离线与重放窗口打开。无约束委派让服务拿用户票再冒充。缺口是：保护域控、限制委派、监控异常 TGT。</p><h3 id="哈希不等于口令" tabindex="-1">哈希不等于口令 <a class="header-anchor" href="#哈希不等于口令" aria-label="Permalink to &quot;哈希不等于口令&quot;">​</a></h3><p>长期密钥材料泄漏可造票。口令策略挡不住已盗的密钥。</p><p><span class="marginnote">RFC 4120。课程禁止 Kerberos 攻击操作指导。只讲：票据是能力，能力过宽则横向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 Linux sudo：域里是委派与 PAC。硬化：约束委派、受保护用户组、KRBTGT 轮换流程。下一课 TEE。</p>',12)),(a(),l(h,null,{default:o(()=>[c(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22TGT%20%E8%83%BD%E5%8A%9B%22%5D%20--%3E%20SVC%5B%22%E6%9C%8D%E5%8A%A1%E7%A5%A8%22%5D%0A%20%20DEL%5B%22%E8%BF%87%E5%AE%BD%E5%A7%94%E6%B4%BE%22%5D%20--%3E%20IMP%5B%22%E5%86%92%E5%85%85%E7%94%A8%E6%88%B7%22%5D%0A%20%20HARD%5B%22%E7%BA%A6%E6%9D%9F%E5%A7%94%E6%B4%BE%E4%B8%8E%E7%9F%AD%E5%AF%BF%E5%91%BD%22%5D%20--%3E%20LIM%5B%22%E7%BC%A9%E5%B0%8F%E8%83%BD%E5%8A%9B%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份在票据里。HSM/TEE 下一课把密钥再往硬件里塞。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写造票步骤。TEE：SGX/TrustZone 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主机提权之外，域票据是横向能力。</li><li>委派与 KRBTGT 是合同核心。</li><li>点名失败模式，不给操作链。</li><li>下一课 TEE。</li><li>出处：RFC 4120；Bellovin and Merritt；Microsoft 委派文档；<a href="/cs/kerberos">kerberos</a>。</li></ul>',8))])}const f=t(p,[["render",E]]);export{m as __pageData,f as default};
